CREATE OR REPLACE FUNCTION lab.highest_paid (p_dept numeric)
RETURNS numeric
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
DECLARE
  l_emp numeric;
BEGIN
  SELECT emp_id INTO STRICT l_emp
    FROM emp
   WHERE dept_id = p_dept
   ORDER BY salary DESC, emp_id
   LIMIT 1;
  RETURN l_emp;
END;
$$;
